/* User-entered spare-parts demo. Historical workbook evidence remains separate. */
(() => {
  'use strict';
  let tab='inventory',query='',filter='all',page=0,dialogState=null,noteDraft='';
  const E=s=>esc(s),N=n=>n==null?'—':num(n,0), isSup=()=>state.role==='Supervisor', canMove=()=>['Supervisor','Technician'].includes(state.role);
  const statuses=['Pending approval','Approved','Partially received','Received','Cancelled'];
  const defaultSite=()=>state.site!=='all'?state.site:DATA.sites.find(s=>s.site_id==='S04')?.site_id||DATA.sites.find(s=>s.site_name==='Arroyo')?.site_id||DATA.sites[0].site_id;
  function store(){if(!window.PartsStore){let storage=null;try{storage=window.localStorage;}catch{}window.PartsStore=window.SparePartsModel.create({sites:DATA.sites,assets:DATA.assets,getRole:()=>state.role,getSafetyGate:id=>window.HSEActionDetails?.gate(id),storage});}return window.PartsStore;}
  const snapshot=()=>store().snapshot(),inScope=x=>state.site==='all'||x.site_id===state.site,items=()=>store().getItems().filter(inScope);
  const allOrders=()=>store().getOrders?store().getOrders():snapshot().orders.map(o=>({...o,remaining_quantity:o.quantity-o.received_quantity})),orders=()=>allOrders().filter(inScope);
  const item=id=>store().getItems().find(x=>x.id===id),order=id=>allOrders().find(x=>x.id===id),openOrders=()=>orders().filter(o=>!['Received','Cancelled'].includes(o.status));
  const rule=id=>{const r=snapshot().siteRules;return Array.isArray(r)?r.find(x=>x.site_id===id)||{enabled:false}:r[id]||{enabled:false};};
  const tick=on=>on?'checked':'',moneyCell=v=>v==null?'Not supplied':money(v),stamp=s=>s?new Date(s).toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'UTC'})+' UTC':'—';
  const btn=(label,action,id='',cls='secondary small',disabled=false)=>`<button type="button" class="btn ${cls}" data-sp-action="${action}" data-sp-id="${E(id)}" ${disabled?'disabled':''}>${E(label)}</button>`;
  const table=(heads,rows)=>`<div class="table-wrap sp-table"><table><thead><tr>${heads.map(h=>`<th>${E(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
  const statusBadge=s=>badge(s==='On order'?'Request open':s,s==='Received'||s==='In stock'?'success':s==='Reorder needed'?'critical':['Pending approval','Partially received','Unconfigured'].includes(s)?'warning':'neutral');
  const field=(label,control,help='',full=false)=>`<label class="sp-field ${full?'full':''}">${E(label)}${control}${help?`<small>${E(help)}</small>`:''}</label>`;
  const input=(id,value='',extra='')=>`<input id="sp-${id}" value="${E(value??'')}" ${extra}>`,select=(id,opts,value)=>`<select id="sp-${id}">${opts.map(([v,l])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(l)}</option>`).join('')}</select>`;
  const textarea=(id,placeholder='Required note')=>`<textarea id="sp-${id}" rows="3" placeholder="${E(placeholder)}" maxlength="500"></textarea>`;
  const val=id=>document.getElementById('sp-'+id)?.value??'',number=id=>val(id)===''?null:Number(val(id));
  const noteChoices=['Noise and vibration increased','Visible leak reported','Protective trip; electrical panel','Feed conditions changed','Cause not confirmed'];
  function noteResult(){
    const result=window.SparePartsModel.suggestKit(noteDraft);
    if(!noteDraft.trim())return '<span class="sp-note-result-label">Suggested kit</span><strong>Choose or type a note</strong><span>Suggestions appear here.</span>';
    return `<span class="sp-note-result-label">Suggested next step</span><strong>${E(result.kit || 'Inspect first')}</strong><span>${result.matched?'Matched to the note-to-kit lookup.':'No single clear match. Confirm the cause before choosing a kit.'}</span>`;
  }
  function updateNote(value){noteDraft=value.slice(0,2000);const area=document.getElementById('sp-smart-note'),preset=document.getElementById('sp-note-preset'),result=document.getElementById('sp-note-result');if(area&&area.value!==noteDraft)area.value=noteDraft;if(preset)preset.value=noteChoices.includes(noteDraft)?noteDraft:'';if(result)result.innerHTML=noteResult();}
  function gateCard(s){
    const g=window.HSEActionDetails?.gate(s.site_id),held=!g||g.held,critical=g?.critical||[],remaining=g?.unresolved||[];
    return `<div class="sp-gate-card ${held?'is-held':'is-clear'}" data-site-id="${E(s.site_id)}"><div class="sp-gate-top"><strong>${E(s.site_name)}</strong>${badge(held?'HOLD':'CLEAR',held?'critical':'success')}</div><p>${!g?'Safety status unavailable; requests locked.':held?`${remaining.length} critical action${remaining.length===1?'':'s'} awaiting HSE verification`:'Requests unlocked · standard approval applies'}</p>${critical.length?`<div class="sp-gate-actions">${critical.map(r=>{const verified=!remaining.some(x=>x.hse_id===r.hse_id);return `<button type="button" data-sp-action="hse-action" data-sp-id="${E(r.hse_id)}" class="sp-gate-action ${verified?'is-verified':''}" aria-label="Review ${E(r.hse_id)} ${E(r.hazard)}"><strong>${E(r.hse_id)}</strong><span>${E(r.hazard)}</span><small>${verified?'Verified closed':E(window.HSEActionDetails.status?.(r.hse_id)||'Open')}</small></button>`;}).join('')}</div>`:''}</div>`;
  }
  function workflowTools(){return `<div class="sp-workflow-tools"><section class="panel sp-smart-notes" aria-labelledby="sp-smart-title"><div class="panel-head"><h2 id="sp-smart-title">Smart note sorting</h2>${badge('Suggested kit')}</div><div class="sp-tools-body"><label class="sp-field" for="sp-note-preset">Pick a common note<select id="sp-note-preset"><option value="">Choose a note</option>${noteChoices.map(n=>`<option value="${E(n)}" ${noteDraft===n?'selected':''}>${E(n)}</option>`).join('')}</select></label><label class="sp-field" for="sp-smart-note">Or type a technician note<textarea id="sp-smart-note" rows="2" maxlength="2000" placeholder="e.g. Noise and vibration increased">${E(noteDraft)}</textarea></label><div id="sp-note-result" class="sp-note-result" role="status" aria-live="polite">${noteResult()}</div><p class="sp-tools-foot">Rule-based suggestion, not a diagnosis. Confirm the kit and follow site procedures.</p></div></section><section class="panel sp-safety-gates" aria-labelledby="sp-gate-title"><div class="panel-head"><h2 id="sp-gate-title">Safety gate</h2>${badge('Demo status')}</div><div class="sp-tools-body"><div class="sp-gate-grid ${state.site==='all'?'all-sites':''}">${[...selectedSites()].sort((a,b)=>(b.site_id==='S04')-(a.site_id==='S04')||Number(window.HSEActionDetails?.gate(b.site_id).held)-Number(window.HSEActionDetails?.gate(a.site_id).held)).map(gateCard).join('')}</div><p class="sp-tools-foot">Requests may queue on HOLD. Approval and receipt unlock only after an HSE Supervisor verifies every critical action. This is a demo gate, not an equipment control.</p></div></section></div>`;}
  function orderGate(o){return store().getSafetyGate(o.site_id);}
  function orderHold(o){const g=orderGate(o);return g.held?`<div class="sp-order-hold" role="status"><strong>HOLD · ${E(siteName(o.site_id))}</strong><span>Request locked until all critical actions have HSE Supervisor verification.</span><div>${(window.HSEActionDetails?.gate(o.site_id)?.unresolved||[]).map(r=>btn('Review '+r.hse_id,'hse-action',r.hse_id)).join('')}</div></div>`:'';}
  function refresh(){if(location.hash==='#parts'||current==='parts')render();}
  function showTab(next){if(!['inventory','orders','automation'].includes(next))return;tab=next;page=0;query='';filter='all';if(location.hash==='#parts')refresh();}
  function resetView(){query='';filter='all';page=0;if(document.querySelector('#modal-body .sp-dialog')){modal.close();document.getElementById('modal-body').innerHTML='';}dialogState=null;}
  function paginate(rows,size=6){page=Math.min(page,Math.max(0,Math.ceil(rows.length/size)-1));return rows.slice(page*size,(page+1)*size);}
  function pagination(total,size=6){return `<div class="sp-pagination"><span>${total?page*size+1:0}–${Math.min(total,(page+1)*size)} of ${total}</span><div>${btn('Previous','prev','','secondary small',page===0)}${btn('Next','next','','secondary small',(page+1)*size>=total)}</div></div>`;}
  function baseline(){const sites=selectedSites(),sourceEvents=DATA.events.filter(e=>e.event_type==='Unplanned');return `<details class="sp-source" ${items().length||window.ArroyoInsights?.renderPartsSummary?'':'open'}><summary>Workbook evidence <small>2025 · historical source values</small></summary>${table(['Site','Source spare fill','Parts-wait hours','Affected events'],sites.map(s=>{const ev=sourceEvents.filter(e=>e.site_id===s.site_id);return `<tr><td><strong>${E(s.site_name)}</strong></td><td>${num(s.spare_fill_pct,0)}%</td><td>${num(sum(ev,'parts_wait_hours'))} h</td><td>${ev.filter(e=>e.parts_wait_hours>0).length}</td></tr>`;}))}<div class="sp-source-foot">Assets / Events · ${E(DATA.meta.file)}. Spare-fill rates are source inputs, not inventory balances.</div></details>`;}
  function inventory(){const all=items(),list=all.filter(i=>(filter==='all'||i.stock_state===filter)&&(!query||(i.sku+' '+i.name+' '+siteName(i.site_id)+' '+(i.asset_id||'')).toLowerCase().includes(query.toLowerCase())));const top=`<div class="sp-toolbar"><div><input id="sp-search" aria-label="Search inventory" placeholder="Search parts or SKU" value="${E(query)}"><select id="sp-status" aria-label="Stock status"><option value="all">All stock states</option>${['Unconfigured','Reorder needed','On order','In stock'].map(s=>`<option ${filter===s?'selected':''}>${s}</option>`).join('')}</select></div>${isSup()?`<div>${btn('Add part','add','','')}${btn('Try demo','demo')}</div>`:''}</div>`;
    if(!all.length)return `<section class="panel sp-tracker-empty"><div class="sp-empty"><div class="sp-empty-icon">${icon('box')}</div><div class="sp-empty-copy"><h3>No demo inventory yet</h3><p>Workbook stock quantities are not supplied. Add a part or try the demo.</p></div><div class="sp-actions">${isSup()?btn('Add part','add','','')+btn('Try demo','demo'):'<span class="subtle">A Supervisor can add demo inventory.</span>'}</div></div></section>`;
    const body=paginate(list).map(i=>`<tr><td class="sp-item"><strong>${E(i.name)}</strong><small>${E(i.sku)}${i.asset_id?' · '+E(i.asset_id):''}</small></td><td>${E(siteName(i.site_id))}</td><td class="sp-number">${N(i.on_hand)}</td><td class="sp-number">${N(i.reorder_point)}</td><td class="sp-number">${N(i.target_stock)}</td><td class="sp-number">${N(i.on_order)}</td><td>${statusBadge(i.stock_state)}</td><td><div class="sp-actions">${canMove()?btn('Issue','issue',i.id,'secondary small',i.on_hand==null||i.on_hand===0)+btn('Count','count',i.id):''}${btn(isSup()?'Edit':'View','item',i.id)}</div></td></tr>`);
    return top+`<section class="panel"><div class="panel-head"><h2>Tracked parts</h2>${badge('User-entered demo')}</div>${body.length?table(['Part / SKU','Site','On hand','Reorder','Target','Open qty','Status',''],body):'<div class="empty">No matching parts</div>'}${pagination(list.length)}</section>`;
  }
  function activity(){const list=snapshot().activity.filter(inScope).slice().reverse().slice(0,12);return `<details class="sp-source"><summary>Demo activity <small>Saved in this browser</small></summary><div class="sp-activity">${list.length?list.map(a=>`<div class="sp-activity-row"><time>${E(stamp(a.at))}</time><div><strong>${E(a.action)}</strong><small>${E(a.actor)} · ${E(siteName(a.site_id))}${a.notes?' · '+E(a.notes):''}${a.quantity!=null?' · Qty '+N(a.quantity):''}</small></div></div>`).join(''):'<div class="empty">No inventory activity yet</div>'}</div></details>`;}
  function orderView(){const list=orders().filter(o=>(filter==='all'||o.status===filter)&&(!query||(o.id+' '+(item(o.item_id)?.name||'')+' '+siteName(o.site_id)).toLowerCase().includes(query.toLowerCase()))).slice().reverse();return `<div class="sp-toolbar"><div><input id="sp-search" aria-label="Search orders" placeholder="Search orders or parts" value="${E(query)}">${select('status',[['all','All order states'],...statuses.map(s=>[s,s])],filter)}</div>${isSup()?btn('Check stock','check'):'<span class="subtle">Requests stay local until reviewed.</span>'}</div><section class="panel"><div class="panel-head"><h2>Replenishment requests</h2>${badge('No supplier connection')}</div>${list.length?table(['Request','Part / site','Requested','Received','Remaining','Status',''],paginate(list).map(o=>{const i=item(o.item_id);return `<tr><td><strong>${E(o.id)}</strong></td><td class="sp-item"><strong>${E(i?.name||o.item_id)}</strong><small>${E(siteName(o.site_id))}</small></td><td>${N(o.quantity)}</td><td>${N(o.received_quantity)}</td><td>${N(o.remaining_quantity)}</td><td>${orderGate(o).held?badge('HSE HOLD','critical')+'<br>':''}${statusBadge(o.status)}</td><td>${btn('View','order',o.id)}</td></tr>`}))+pagination(list.length):'<div class="sp-empty"><h3>No replenishment requests</h3><p>Enabled site rules create requests when stock reaches its reorder point.</p></div>'}</section>`+activity();}
  function automation(){return `<section class="panel"><div class="panel-head"><h2>Site replenishment rules</h2>${isSup()?btn('Check stock','check'):badge('Read only')}</div>${table(['Site','Automation','Safety gate','Configured parts','Open requests',''],selectedSites().map(s=>{const all=store().getItems().filter(i=>i.site_id===s.site_id),configured=all.filter(i=>i.on_hand!=null&&i.reorder_point!=null&&i.target_stock!=null),open=allOrders().filter(o=>o.site_id===s.site_id&&!['Received','Cancelled'].includes(o.status));return `<tr><td><strong>${E(s.site_name)}</strong></td><td><label class="sp-rule"><input type="checkbox" data-sp-rule="${E(s.site_id)}" ${tick(rule(s.site_id).enabled)} ${isSup()?'':'disabled'}> ${rule(s.site_id).enabled?'Enabled':'Off'}</label></td><td>${badge(store().getSafetyGate(s.site_id).held?'HOLD':'CLEAR',store().getSafetyGate(s.site_id).held?'critical':'success')}</td><td>${configured.length} / ${all.length}</td><td>${open.length}</td><td>${isSup()?btn('Add part','add-site',s.site_id):''}</td></tr>`;}))}<div class="sp-rule-note">Demo inventory position = on hand + open request quantity. At or below the reorder point → request the gap to target. HSE clearance unlocks approval and receipt; a Supervisor approves each request.</div></section>${isSup()?`<div class="sp-toolbar"><span class="subtle">Automation never sends an order to a supplier.</span>${btn('Reset spare-parts demo','reset','','secondary small')}</div>`:''}`;}
  function trackingSummary(all,os,selected){
    const missing=all.filter(i=>i.on_hand==null).length,needs=all.filter(i=>i.stock_state==='Reorder needed').length,stages=[['In stock','ready'],['Reorder needed','low'],['On order','requested'],['Unconfigured','unknown']].map(([key,color])=>({key,color,label:key==='On order'?'Request open':key,count:all.filter(i=>i.stock_state===key).length}));
    const requestRows=orders(),progress=[['Pending approval','Pending'],['Approved','Approved'],['Partially received','Partial'],['Received','Received']],cancelled=requestRows.filter(o=>o.status==='Cancelled').length;
    return `<div class="sp-tracker-kpis">${stat('Tracked SKUs',all.length,missing?missing+' stock count'+(missing===1?'':'s')+' missing':all.length?'All stock counts entered':'Demo records only')}${stat('Reorder needed',needs,'Configured parts',needs?'critical':'')}${stat('Open requests',os.length,'Awaiting approval / receipt')}${stat('Rules enabled',selected.filter(s=>rule(s.site_id).enabled).length+' / '+selected.length,'Selected sites')}</div><div class="sp-tracker-meters"><section class="sp-stock-summary" aria-label="Demo stock status"><div class="sp-meter-heading"><h3>Stock status</h3><span>${all.length?all.length+' tracked SKU'+(all.length===1?'':'s'):'No demo stock records'}</span></div><div class="sp-stock-meter" role="img" aria-label="${E(all.length?stages.map(s=>s.label+': '+s.count).join(', '):'No demo stock records. Workbook quantities are not supplied.')}" >${all.length?stages.filter(s=>s.count).map(s=>`<span class="sp-stock-segment sp-stock-${s.color}" style="width:${s.count/all.length*100}%" title="${E(s.label)}: ${s.count}"></span>`).join(''):'<span class="sp-stock-placeholder"></span>'}</div><div class="sp-stock-key">${stages.map(s=>`<span><i class="sp-stock-${s.color}"></i>${E(s.label)} <strong>${s.count}</strong></span>`).join('')}</div></section><section class="sp-request-summary" aria-label="Demo request progress"><div class="sp-meter-heading"><h3>Request progress</h3><span>${cancelled?cancelled+' cancelled':'Demo requests'}</span></div><div class="sp-request-counts">${progress.map(([key,label])=>`<div><strong>${requestRows.filter(o=>o.status===key).length}</strong><span>${label}</span></div>`).join('')}</div></section></div>`;
  }
  function view(){const all=items(),os=openOrders(),selected=selectedSites(),storageState=store().storageStatus(),mode=storageState.mode,summary=typeof window.ArroyoInsights?.renderPartsSummary==='function'?window.ArroyoInsights.renderPartsSummary():'';return `<div class="sp-workspace">${workflowTools()}${summary}<section class="sp-tracker" aria-labelledby="sp-tracker-title"><div class="sp-tracker-heading"><div><h2 id="sp-tracker-title">Inventory tracker</h2><p>Browser-local demo · separate from workbook history</p></div><span class="sp-tracker-scope">${state.site==='all'?'All sites':E(siteName(state.site))}</span></div><div class="sp-note sp-tracker-storage"><span>${storageState.error?E(storageState.error):mode==='memory'?'Session only; browser storage unavailable.':'Saved in this browser.'} No supplier connection.</span><span>${E(state.role)} view</span></div>${trackingSummary(all,os,selected)}<div class="sp-tabs" role="tablist">${[['inventory','Inventory'],['orders','Orders'],['automation','Automation']].map(([id,l])=>`<button class="sp-tab ${tab===id?'active':''}" data-sp-action="tab" data-sp-id="${id}" role="tab" aria-selected="${tab===id}">${l}${id==='orders'&&os.length?`<span class="badge neutral">${os.length}</span>`:''}</button>`).join('')}</div>${({inventory,orders:orderView,automation})[tab]()}</section>${baseline()}</div>`;}
  function dialog(title,body,ctx){dialogState=ctx;openModal(title,`<div class="sp-dialog">${body}<div class="sp-error" id="sp-error" role="alert"></div></div>`);}
  const note=()=>'<div class="sp-note">User-entered demo data · separate from workbook records</div>';
  const footer=(label,action,id='')=>`<div class="sp-dialog-footer">${btn('Cancel','close')}${btn(label,action,id,'')}</div>`;
  function assetOptions(site){return [['','Site-level spare'],...DATA.assets.filter(a=>a.site_id===site).map(a=>[a.asset_id,a.asset_id+' · '+a.asset_type])];}
  function openAdd(site){if(!isSup())return false;openItem(null,site);return true;}
  function openItem(id,site){const i=id?item(id):null;if(id&&(!i||!inScope(i)))return false;const editing=!!i,readOnly=!isSup(),sid=i?.site_id||site||defaultSite(),lock=readOnly?'disabled':'';
    const siteSelect=select('site',DATA.sites.map(s=>[s.site_id,s.site_name]),sid).replace('<select','<select '+(editing?'disabled':''));const fields=field('Site',siteSelect)+field('Asset',select('asset',assetOptions(sid),i?.asset_id||'').replace('<select','<select '+lock))+field('SKU',input('sku',i?.sku||'',`maxlength="60" required ${lock}`))+field('Part name',input('name',i?.name||'',`maxlength="100" required ${lock}`))+(editing?field('On hand',input('on-hand',i?.on_hand,'disabled'),'Use Count to record a stock adjustment.'):field('Opening count',input('on-hand','',`type="number" min="0" step="1"`),'Leave blank if unknown.'))+field('Reorder point',input('reorder',i?.reorder_point,`type="number" min="0" step="1" ${lock}`),'At or below this count triggers a request.')+field('Target stock',input('target',i?.target_stock,`type="number" min="0" step="1" ${lock}`),'Target must exceed the reorder point.')+field('Supplier (optional)',input('supplier',i?.supplier||'',`maxlength="100" ${lock}`))+ (isSup()?field('Unit cost, USD (optional)',input('cost',i?.unit_cost_usd,`type="number" min="0" step="0.01"`),'Demo input; no price supplied by the workbook.'):'');
    dialog(editing?i.name:'Add demo part',note()+`<div class="sp-form">${fields}</div>`+(readOnly?'<div class="sp-dialog-footer">'+btn('Close','close')+'</div>':footer(editing?'Save changes':'Add part','save-item',id||'')),{kind:'item',id,site:sid});return true;
  }
  function movement(id,kind){const i=item(id);if(!i||!canMove())return false;dialog(kind==='issue'?'Issue stock · '+i.name:'Stock count · '+i.name,note()+`<div class="sp-count-change"><span>Current on hand</span><strong>${N(i.on_hand)}</strong></div><div class="sp-form">${field(kind==='issue'?'Quantity to issue':'New on-hand count',input('quantity',kind==='count'?i.on_hand:'',`type="number" min="${kind==='issue'?1:0}" step="1" required ${kind==='issue'&&i.on_hand!=null?'max="'+i.on_hand+'"':''}`))}${field('Movement note',textarea('note','Required · demo usage or count reference'),'',true)}</div><div class="sp-draft-notice">${rule(i.site_id).enabled?'Site automation is enabled. Eligible shortages create a pending request.':'Site automation is off.'}</div>`+footer(kind==='issue'?'Issue stock':'Save count','save-movement',id),{kind,id});return true;}
  const facts=rows=>`<dl class="sp-facts">${rows.map(([k,v])=>`<div><dt>${E(k)}</dt><dd>${E(v)}</dd></div>`).join('')}</dl>`;
  function openOrder(id){const o=order(id);if(!o||!inScope(o))return false;const i=item(o.item_id),stage=['Pending approval','Approved','Partially received','Received'],idx=stage.indexOf(o.status);let body=note()+orderHold(o)+`<div class="sp-order-stages">${stage.map((s,n)=>`${n?'<i>→</i>':''}<span class="${n===idx?'active':n<idx?'complete':''}">${s}</span>`).join('')}${o.status==='Cancelled'?statusBadge('Cancelled'):''}</div>`+facts([['Part / SKU',(i?.name||o.item_id)+' / '+(i?.sku||'')],['Site',siteName(o.site_id)],['Requested',N(o.quantity)],['Received / remaining',N(o.received_quantity)+' / '+N(o.remaining_quantity)],['Supplier',o.supplier||'Not supplied'],['Reason',o.reason||'Replenishment']].concat(isSup()?[['Unit cost',moneyCell(o.unit_cost_usd)],['Request value',o.unit_cost_usd==null?'Not supplied':money(o.unit_cost_usd*o.quantity)]]:[]));
    if(isSup()&&o.status==='Pending approval')body+=`<div class="sp-dialog-section"><h3>Supervisor review</h3>${field('Approval note',textarea('approval','Required · approval rationale'))}<div class="sp-actions">${btn('Approve request','approve',id,'',orderGate(o).held)}${btn('Cancel request','cancel-order',id)}</div></div>`;
    if(canMove()&&['Approved','Partially received'].includes(o.status))body+=`<div class="sp-dialog-section"><h3>Receive stock</h3><div class="sp-form">${field('Quantity received',input('receipt-quantity','',`type="number" min="1" step="1" max="${o.remaining_quantity}" required`))}${field('Receipt reference',input('receipt-reference','',`maxlength="100" required`),'Use a unique demo reference for each delivery.')}</div><div class="sp-dialog-footer">${isSup()?btn('Cancel remainder','cancel-order',id):''}${btn('Record receipt','receive',id,'',orderGate(o).held)}</div></div>`;
    const notes=snapshot().activity.filter(a=>a.order_id===id);body+=`<details class="sp-source"><summary>Request history <small>${notes.length} updates</small></summary><div class="sp-activity">${notes.map(a=>`<div class="sp-activity-row"><time>${E(stamp(a.at))}</time><div><strong>${E(a.action)}</strong><small>${E(a.actor)}${a.notes?' · '+E(a.notes):''}</small></div></div>`).join('')||'<div class="empty">No activity yet</div>'}</div></details>`;dialog(o.id+' · '+o.status,body,{kind:'order',id});return true;
  }
  function openDemo(){if(!isSup())return false;const sid=defaultSite();dialog('Try replenishment · demo','<p>Create one clearly simulated spare at a selected site. Starting stock: <strong>4</strong>, reorder point: <strong>2</strong>, target: <strong>8</strong>. No price is added.</p>'+field('Demo site',select('demo-site',DATA.sites.map(s=>[s.site_id,s.site_name]),sid))+'<div class="sp-draft-notice">Site automation will be enabled. Then issue 3 units to queue a request for 7. A site on HOLD needs HSE verification before approval or receipt.</div>'+footer('Create demo spare','seed'),{kind:'demo'});return true;}
  function resetDialog(){if(!isSup())return;dialog('Reset spare-parts demo','<p>Remove all user-entered spare parts, requests, automation settings and spare-parts activity from this browser?</p><p>Workbook records and HSE activity stay unchanged.</p>'+footer('Reset spare-parts data','confirm-reset'),{kind:'reset'});}
  function error(e){const box=document.getElementById('sp-error');if(box)box.textContent=e.message||String(e);else toast(e.message||String(e));}
  function done(message,keep){refresh();if(keep)keep();else{modal.close();dialogState=null;}if(message)toast(message);}
  document.addEventListener('click',event=>{const b=event.target.closest('[data-sp-action]');if(!b||b.disabled)return;const a=b.dataset.spAction,id=b.dataset.spId;try{
    if(a==='hse-action'){dialogState=null;window.HSEActionDetails.open(id);return;}
    if(a==='tab')showTab(id);if(a==='prev'){page=Math.max(0,page-1);refresh();}if(a==='next'){page++;refresh();}if(a==='add')openAdd();if(a==='add-site')openAdd(id);if(a==='item')openItem(id);if(a==='order')openOrder(id);if(a==='demo')openDemo();if(a==='issue'||a==='count')movement(id,a);if(a==='close'){modal.close();dialogState=null;}
    if(a==='save-item'){if(!isSup())throw Error('Only a Supervisor can configure parts.');const patch={site_id:val('site'),asset_id:val('asset')||null,sku:val('sku'),name:val('name'),reorder_point:number('reorder'),target_stock:number('target'),supplier:val('supplier')||null,unit_cost_usd:number('cost')};if(id){delete patch.site_id;store().updateItem(id,patch);}else{patch.on_hand=number('on-hand');store().addItem(patch);}done(id?'Demo part updated.':'Demo part added.');}
    if(a==='save-movement'){const kind=dialogState?.kind;if(kind==='issue')store().issue(id,number('quantity'),val('note'));else if(kind==='count')store().adjust(id,number('quantity'),val('note'));else throw Error('Open a stock movement first.');done('Demo stock updated. Replenishment rules checked.');}
    if(a==='approve'){store().approve(id,val('approval'));done('Demo request approved. No supplier order was sent.',()=>openOrder(id));}
    if(a==='cancel-order')dialog('Cancel '+id,field('Cancellation reason',textarea('cancel-reason','Required · cancellation reason'))+footer('Cancel request','save-cancel',id),{kind:'cancel',id});
    if(a==='save-cancel'){store().cancel(id,val('cancel-reason'));done('Demo request cancelled.',()=>openOrder(id));}
    if(a==='receive'){store().receive(id,number('receipt-quantity'),val('receipt-reference'));done('Receipt saved to demo inventory.',()=>openOrder(id));}
    if(a==='check'){const result=store().check(state.site);refresh();toast((Array.isArray(result.created)?result.created.length:result.created||0)+' replenishment request(s) created.');}
    if(a==='seed'){const sid=val('demo-site');store().seedDemo(sid);modal.close();dialogState=null;tab='inventory';if(state.site!==sid)changeSite(sid);else refresh();toast('Simulated spare added. Issue 3 units to try replenishment.');}
    if(a==='reset')resetDialog();if(a==='confirm-reset'){store().reset();noteDraft='';query='';filter='all';page=0;tab='inventory';done('Spare-parts demo reset. HSE records are unchanged.');}
  }catch(e){error(e);}});
  document.addEventListener('change',event=>{const el=event.target;try{if(el.id==='sp-note-preset'){updateNote(el.value);return;}if(el.id==='sp-status'){filter=el.value;page=0;refresh();}if(el.id==='sp-site'&&dialogState?.kind==='item'&&!dialogState.id){const target=document.getElementById('sp-asset');target.innerHTML=assetOptions(el.value).map(([v,l])=>`<option value="${E(v)}">${E(l)}</option>`).join('');}if(el.dataset.spRule){store().setAutomation(el.dataset.spRule,el.checked);refresh();}}catch(e){error(e);refresh();}});
  document.addEventListener('input',event=>{if(event.target.id==='sp-smart-note'){updateNote(event.target.value);return;}if(event.target.id!=='sp-search')return;const old=event.target.selectionStart;query=event.target.value;page=0;refresh();const box=document.getElementById('sp-search');if(box){box.focus();box.setSelectionRange(old,old);}});
  window.addEventListener('viewchange',resetView);
  window.addEventListener('hse-demo-change',()=>{refresh();if(dialogState?.kind==='order'&&modal.open)openOrder(dialogState.id);});
  store();
  window.SpareParts=Object.freeze({render:view,openAdd,openDemo,openOrder,openItem,showTab,resetView});
})();
